// Fakty dla modelu językowego i gotowy post awaryjny — liczby WYŁĄCZNIE ze skrótu dnia.
const cfg = $('Konfiguracja').first().json;
const b = $input.first().json;
const p = b.public || {};
const godz = (iso) => new Date(iso).toLocaleTimeString('pl-PL', { timeZone: 'Europe/Warsaw', hour: '2-digit', minute: '2-digit' });
const link = (url) => `${url}${url.includes('?') ? '&' : '?'}${cfg.utm}`;
const wynik = { won: 'trafiony', lost: 'chybiony', void: 'anulowany', pending: 'w grze' };
const kuponWynik = { won: 'wszedł', lost: 'nie wszedł', void: 'anulowany', pending: 'w grze', none: 'nie było kuponu' };

const fakty = [];
const szablon = [];
const dozwolone = new Set();
const liczby = (s) => (String(s ?? '').match(/\d+(?:[.,]\d+)?/g) || []).forEach((n) => dozwolone.add(String(Number(n.replace(',', '.')))));
dozwolone.add('18');

const t = p.dailyPick;
if (t) {
  const linia = `TYP DNIA: ${t.match} (${t.league}), start ${godz(t.kickoff)}. Typ: ${t.selection}. Model: ${t.probability}% (zwykle w takich meczach ~${t.usually}%). Link: ${link(t.url)}`;
  fakty.push(linia);
  szablon.push(`⚽ Typ dnia: ${t.match}, ${godz(t.kickoff)}\n👉 ${t.selection} — model ${t.probability}% (zwykle ~${t.usually}%)`);
  liczby(linia);
}
const k = p.coupon;
if (k && k.legs?.length) {
  const nogi = k.legs.map((l) => `- ${l.match}: ${l.selection} @ ${l.oddsText} (${godz(l.kickoff)})`).join('\n');
  const linia = `KUPON DNIA (za darmo): kurs łączny ${k.totalOddsText}, szansa według modelu ${k.chance}%. Mecze:\n${nogi}`;
  fakty.push(linia);
  szablon.push(`🎟️ Kupon dnia: kurs ${k.totalOddsText}, szansa wg modelu ${k.chance}%\n${nogi}`);
  liczby(linia);
}
const w = p.dailyPickYesterday;
const kw = p.couponYesterday;
if (w || kw) {
  const czesci = [];
  if (w) czesci.push(`typ dnia ${w.match} — ${w.selection}: ${wynik[w.status] || w.status}${w.score ? ` (${w.score})` : ''}`);
  if (kw) czesci.push(`kupon dnia: ${kuponWynik[kw.status] || kw.status}${kw.totalOddsText ? ` (kurs ${kw.totalOddsText})` : ''}`);
  const linia = `WCZORAJ (podaj uczciwie, także przegrane): ${czesci.join('; ')}.`;
  fakty.push(linia);
  szablon.push(`📊 Wczoraj: ${czesci.join('; ')}`);
  liczby(linia);
}
const r = p.dailyPickRecord;
const a = p.accuracy30;
if (r || a) {
  const linia = `DOROBEK: typ dnia ${r?.won ?? 0} z ${r?.total ?? 0} trafionych; skuteczność 30 dni: ${a?.hitRate ?? '—'}% na ${a?.settled ?? 0} rozliczonych typach (zwykle w takich zdarzeniach ~${a?.usually ?? '—'}%).`;
  fakty.push(linia);
  liczby(linia);
}

const stopka = `\n\nWszystkie typy i analizy: ${link(p.siteUrl + '/pl/typy-na-dzis')}\nSzacunki, nie pewniaki. Serwis nie przyjmuje zakładów. 18+`;
const system = [
  'Piszesz krótki, poranny post na kanał Telegram serwisu Czat Sportowy (analizy meczów piłkarskich oparte na modelu statystycznym).',
  'ZASADY, KTÓRYCH NIE WOLNO ŁAMAĆ:',
  '1. Liczby (procenty, kursy, godziny, wyniki, dorobek) przepisujesz WYŁĄCZNIE z FAKTÓW, co do znaku. Nie dodajesz żadnej innej liczby ani daty.',
  '2. Nie piszesz: pewniak, pewna wygrana, gwarancja, zarobek, postaw, stawka; nie wymieniasz bukmacherów; nie zachęcasz do gry.',
  '3. Wczorajszy wynik podajesz uczciwie, także gdy przegraliśmy — jednym zdaniem, bez tłumaczenia się.',
  '4. Najwyżej 600 znaków, po polsku, konkretnie, 2–4 emoji. Bez hashtagów. Bez stopki i bez linku do strony głównej — dopisze je system.',
  '5. Link do typu dnia przepisz dokładnie z FAKTÓW.'
].join('\n');

return [{ json: {
  maCo: Boolean(t || (k && k.legs?.length)),
  fakty: fakty.join('\n\n'),
  szablon: szablon.join('\n\n') + (t ? `\n${link(t.url)}` : '') + stopka,
  stopka,
  dozwolone: [...dozwolone],
  druzyny: t ? t.match.split(' – ') : [],
  requestBody: {
    model: cfg.model,
    // Bez rozumowania: inaczej limit tokenów idzie na myślenie i odpowiedź przychodzi pusta.
    ...(cfg.reasoningEffort ? { reasoning_effort: cfg.reasoningEffort } : {}),
    max_completion_tokens: 700,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: `FAKTY:\n\n${fakty.join('\n\n')}\n\nNapisz post.` }
    ]
  }
} }];

// Bezpiecznik: post od LLM idzie tylko wtedy, gdy nie zmyśla liczb i trzyma zasady. Inaczej — szablon z samych faktów.
const f = $('Przygotuj fakty i szablon').first().json;
const odp = $input.first().json;
const tekst = String(odp?.choices?.[0]?.message?.content || '').trim();
const powody = [];

if (!tekst) powody.push('brak odpowiedzi modelu' + (odp?.error ? `: ${JSON.stringify(odp.error).slice(0, 120)}` : ''));
if (tekst.length > 700) powody.push(`za długi (${tekst.length} znaków)`);
if (/pewniak|pewn[aey] wygran|gwarant|zarob|postaw|stawk|\bsts\b|fortuna|betclic|superbet|etoto|totalbet|betfan|lvbet/i.test(tekst)) powody.push('zakazane słowo');
const dozwolone = new Set(f.dozwolone);
const obce = (tekst.match(/\d+(?:[.,]\d+)?/g) || []).map((n) => String(Number(n.replace(',', '.')))).filter((n) => !dozwolone.has(n));
if (obce.length) powody.push(`liczby spoza faktów: ${[...new Set(obce)].join(', ')}`);
if (f.druzyny.length && !f.druzyny.some((d) => tekst.includes(d))) powody.push('brak meczu typu dnia');

const ok = powody.length === 0;
return [{ json: {
  post: ok ? tekst + f.stopka : f.szablon,
  zrodlo: ok ? 'llm' : 'szablon',
  powody,
  tokeny: odp?.usage?.total_tokens ?? null
} }];
